    name="cute_conv2d_bf16_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_bf16_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.in_channels = 3
        self.out_channels = 32
        self.kernel_size = (3, 3)
        # Match nn.Conv2d default init for weight, no bias
        self.weight = nn.Parameter(
            torch.empty(self.out_channels, self.in_channels,
                        self.kernel_size[0], self.kernel_size[1],
                        dtype=torch.bfloat16)
        )
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)
        self._ext = conv2d_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv2d_bf16_forward(x.contiguous(), self.weight.contiguous())

